// ❌ OLD: A client-side modal with local state. Clicking a photo opens
// an overlay, but the URL does not change: no deep link, no share,
// refresh loses the modal, and back-button doesn't close it.
'use client';
import { useState } from 'react';
import { PhotoModal } from '@/components/photo-modal';

export default function FeedPage({ photos }: { photos: { id: string }[] }) {
  const [activeId, setActiveId] = useState<string | null>(null); // ❌ OLD

  return (
    <div>
      {photos.map((p) => (
        <button key={p.id} onClick={() => setActiveId(p.id)}>Photo {p.id}</button>
      ))}
      {activeId && <PhotoModal id={activeId} onClose={() => setActiveId(null)} />}
      {/* ❌ OLD: URL stays /feed — modal is invisible to the URL */}
    </div>
  );
}

// ✅ NEW: The intercepting route renders the photo as a modal when
// navigated to from /feed, while the URL becomes /photo/1 (deep
// linkable, refreshable). A hard refresh shows the real photo page.
import PhotoView from '@/components/photo-view';

export default async function InterceptedPhoto({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  return (
    // ✅ NEW: rendered inside the @modal parallel slot in the layout
    <div className="modal">
      <PhotoView id={id} />
    </div>
  );
}

